def decide(catalog, prev, requested, approver, requested_by, admins, mode):
    # catalog: set of read-only scopes for the app; prev: approved set (empty on first connect)
    req = set(requested)
    outside = req - catalog
    if outside:
        # reject the whole request, never drop scopes silently
        return Deny('scope_not_in_catalog', sorted(outside))
    if approver not in admins:
        return Deny('not_admin', [])
    if mode == 'app_only' and approver == requested_by:
        return Deny('self_approval', [])   # tenant-wide grants need a second person
    added, removed = req - prev, prev - req
    return Approve(approved=sorted(req), added=sorted(added), removed=sorted(removed))

def approve(conn, tenant, app, d, approver, expected_version):
    # compare-and-set: the tricky part. Two admins can approve at once.
    cur = conn.execute('''UPDATE consent SET approved_scopes=%s, approver_id=%s,
          approved_at=now(), review_due=now()+interval '180 days', version=version+1
          WHERE tenant_id=%s AND app_id=%s AND version=%s''',
          (d.approved, approver, tenant, app, expected_version))
    if cur.rowcount == 0:
        raise StaleVersion()   # second admin must re-read the diff and confirm again
    audit(conn, tenant, app, approver, 'approve', d.added, d.removed)

