ALLOWED = {'sync', 'sweep', 'acl_sync', 'backfill'}
DENIED = {'query', 'answer'}

def issue_app_token(vault, catalog, consents, audit, tenant, app, purpose, caller):
    # the tricky part: a user question must never run on the all-seeing app token
    if purpose in DENIED or purpose not in ALLOWED:
        audit(tenant, app, 'app_only', purpose, caller, ok=False)
        raise PurposeDenied(purpose)
    consent = consents.get(tenant, app)          # approved by an admin in so_admin
    if consent is None or consent.mode != 'app_only':
        raise NotConsented(tenant, app)
    readonly = set(catalog.read_only_scopes(app))
    requested = set(consent.approved_scopes)
    if requested - readonly:                      # catalog drifted after approval
        raise ScopeOutsideCatalog(sorted(requested - readonly))
    tok = vault.get_or_refresh(tenant, '__app__', app, scopes=sorted(requested & readonly))
    audit(tenant, app, 'app_only', purpose, caller, ok=True)
    return AppToken(tok.token, tok.expires_at, sorted(requested & readonly), 'app_only')
